149	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
150	// then run the resolved engine standalone with `extra` (model flags the
151	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
152	// `clean_output` picks how the engine's output is presented: fast inherits the
153	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
154	// semihosting console works unchanged); cycle filters out the engine's banner +
155	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
156	// exit code propagates. The per-model engine + selection are resolved by the
157	// caller; `model` here only labels the positional diagnostics.
158	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
159	                   const char* model, const std::vector<std::string>& extra = {},
160	                   bool clean_output = false) {
161	  if (int rc = check_one_elf(cli, model)) return rc;
162	  // QEMU's -bios flag searches its data directory for relative paths rather
163	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
164	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
165	  if (elf.empty()) return 2;
166	  std::vector<std::string> args = extra;
167	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
168	  std::string err;
169	  const std::vector<std::string> argv =
170	      passthrough_argv(eng, "standalone", elf, args, err);
171	  if (!err.empty()) {
172	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
173	    return 2;
174	  }
175	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
176	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
177	  if (cli.dry_run)
178	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
179	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
180	}
