585	  }
586	  if (!find_model(cli.model)) {
587	    std::fprintf(stderr,
588	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
589	                 cli.model.c_str());
590	    return 2;
591	  }
592	  if (!cli.gdb_port.empty() && !cli.gdb) {
593	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
594	    return 2;
595	  }
596	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
597	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
598	  if (cli.gdb && cli.model == "hybrid") {
599	    std::fprintf(stderr,
600	                 "andesim run: --gdb is not supported with --mode hybrid\n");
601	    return 2;
602	  }
603	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
604	  // composition has a second engine to check.
605	  if (cli.verify && cli.model != "hybrid") {
606	    std::fprintf(stderr,
607	                 "andesim run: --verify requires --mode hybrid (the %s "
608	                 "model has nothing to cross-check)\n",
609	                 cli.model.c_str());
610	    return 2;
611	  }
612	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
613	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
614	  // handoff builds itself, so there is no single "the engine" to forward to.
615	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
616	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
617	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
618	    std::fprintf(stderr,
619	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
620	                 "builds both legs' command lines; use --kanata/--objdump for "
621	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
622	    return 2;
623	  }
624	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
625	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
626	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
627	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
628	  // window), so reject instead of measuring something the user did not ask for.
629	  if (!cli.trigger.empty() && cli.model != "hybrid") {
630	    std::fprintf(stderr,
631	                 "andesim run: --trigger applies only to --mode hybrid "
632	                 "(the ROI delimiter); fast/cycle run the whole program\n");
633	    return 2;
634	  }
635	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
636	    std::fprintf(stderr,
637	                 "andesim run: --pc-end applies only to --mode hybrid "
638	                 "--trigger pc\n");
639	    return 2;
640	  }
641	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
642	    std::fprintf(stderr,
643	                 "andesim run: --pc-start applies only to --mode hybrid "
644	                 "--trigger pc\n");
645	    return 2;
646	  }
647	  if (cli.model == "fast") return run_fast(cli);
648	  if (cli.model == "cycle") return run_accurate(cli);
649	  return run_hybrid(cli);  // model validated above; only hybrid remains
