// Repo-root discovery for andesim.
//
// The driver shells out to repo scripts (scripts/build_*.sh), reads fixtures
// (tests/fixtures/), and scans the engines dir -- all relative to the repo
// root. The root is found from the executable's own location via
// /proc/self/exe, so it works regardless of the caller's CWD and for both
// layouts: build/andesim during development and a repo-root andesim after
// the F14 swap.
#ifndef ANDESIM_REPO_ROOT_HPP
#define ANDESIM_REPO_ROOT_HPP

#include <climits>
#include <filesystem>
#include <stdexcept>
#include <string>

#include <unistd.h>

namespace andes_sim {

// Absolute path to this executable, resolved through /proc/self/exe.
inline std::filesystem::path exe_path() {
  char buf[PATH_MAX];
  ssize_t n = ::readlink("/proc/self/exe", buf, sizeof(buf) - 1);
  if (n < 0) throw std::runtime_error("readlink(/proc/self/exe) failed");
  buf[n] = '\0';
  return std::filesystem::path(buf);
}

// Nearest ancestor of the executable that looks like this repo's root,
// identified by two stable markers that travel together: the setup.sh build
// entry point and the shared ABI header. Throws if no such ancestor exists.
inline std::filesystem::path repo_root() {
  namespace fs = std::filesystem;
  // Pure function of /proc/self/exe and the on-disk layout, both stable for the
  // life of the process, so compute it once. (If discovery fails the throwing
  // initializer just re-runs on the next call.)
  static const fs::path root = [] {
    fs::path start = exe_path().parent_path();
    for (fs::path p = start;; p = p.parent_path()) {
      if (fs::exists(p / "setup.sh") &&
          fs::exists(p / "include" / "hybrid" / "state_abi.h"))
        return p;
      if (p == p.root_path()) break;
    }
    throw std::runtime_error("repo root not found above " + start.string());
  }();
  return root;
}

// The bundled QEMU plugin's default location under the repo root. Callers
// that honor a $VSIM_PLUGIN override apply it themselves (cmd_doctor's
// artifact table, run_plan's resolve_plugin); this is the single source for
// the in-repo path.
inline std::filesystem::path default_plugin_path() {
  return repo_root() / "qemu_plugin" / "libhybrid_handoff.so";
}

}  // namespace andes_sim

#endif  // ANDESIM_REPO_ROOT_HPP
===== engine_descriptor.hpp =====
// EngineDescriptor: the parsed result of an engine's `--describe` (or its
// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
// future engines (alioth, sid) speak to join the framework -- see
// docs/engine_interface.md. The framework keeps zero per-engine code; every
// capability it needs comes from here.
#ifndef ANDESIM_ENGINE_DESCRIPTOR_HPP
#define ANDESIM_ENGINE_DESCRIPTOR_HPP

#include <string>
#include <string_view>
#include <vector>

#include "json.hpp"

namespace andes_sim {

// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
// plan executor (F6).
struct EngineInvoke {
  std::string role;
  std::vector<std::string> argv;
};

struct EngineDescriptor {
  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
  std::string type;                     // qemu | verilator | alioth | sid
  std::string kind;                     // functional | cycle-accurate
  long vlen = 0;                        // RVV params; 0 = not reported
  long dlen = 0;
  long elen = 0;
  long xlen = 0;
  std::vector<std::string> triggers;    // marker | pc
  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
  std::vector<std::string> andes_csrs;  // Andes CSRs this engine implements; the
                                        // --verify gate (empty = compare all)
  std::vector<EngineInvoke> invoke;     // argv template per role
  std::string result;                   // stderr:<re> | state.mcycle

  // Filled by the registry, not present in the JSON:
  std::string bin_path;                 // resolved path to the binary
  std::string source;                   // built-in | --describe | sidecar

  const std::vector<std::string>* invoke_for(std::string_view role) const {
    for (const EngineInvoke& iv : invoke)
      if (iv.role == role) return &iv.argv;
    return nullptr;
  }
};

// Build a descriptor from parsed JSON. Returns "" on success or an error
// message naming the first problem (id and type are required).
inline std::string descriptor_from_json(const json::Value& v,
                                        EngineDescriptor& out) {
  if (!v.is_object()) return "descriptor is not a JSON object";

  const json::Value* id = v.find("id");
  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
  out.id = id->as_string();

  const json::Value* type = v.find("type");
  if (!type || !type->is_string()) return "missing string 'type'";
  out.type = type->as_string();

  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
  if (const json::Value* x = v.find("dlen")) out.dlen = x->as_int();
