// The phase-plan executor (F6) -- the C++ analog of runner.run_session, minus
// the dropped QEMU2 handback. run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and checks each leg drained cleanly.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDESIM_RUN_PLAN_HPP
#define ANDESIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
};

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = 200;        // drain success code (kExitHandoffToQemu)
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
};

// Execute `plan`: resolve the plugin, spawn each leg with a timeout, and
// require exit == expect_rc. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it. The
// shared-mmap backing and the per-leg mcycle/minstret readback land with the
// hybrid feature; this single-phase slice threads the argvs and spawns each leg.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDESIM_RUN_PLAN_HPP

// The phase-plan executor. See run_plan.hpp.
#include "run_plan.hpp"

#include <cstdlib>
#include <filesystem>
#include <map>

#include <unistd.h>

#include "argv.hpp"
#include "process.hpp"
#include "repo_root.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
std::string state_path(const std::string& workdir, size_t i) {
  return workdir + "/state-" + std::to_string(i) + ".bin";
}

const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
                                    const std::string& id) {
  for (const EngineDescriptor& e : engines)
    if (e.id == id) return &e;
  return nullptr;
}

// $VSIM_PLUGIN else the in-repo default (matches the e2e harness).
std::string resolve_plugin(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
  return default_plugin_path().string();
}

}  // namespace

std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
  std::vector<std::vector<std::string>> out;
  out.reserve(plan.steps.size());
  std::string prev_state_out;  // empty for the cold first leg

  for (size_t i = 0; i < plan.steps.size(); ++i) {
    const Step& step = plan.steps[i];
    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
    if (!eng) {
      err = "plan step " + std::to_string(i) + ": unknown engine '" +
            step.engine_id + "'";
      return {};
    }
    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
    if (!tmpl) {
      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
            "' has no invoke template for role '" + step.role + "'";
      return {};
    }

    const std::string state_out = state_path(workdir, i);
    const std::map<std::string, std::string> m = {
        {"bin", eng->bin_path},
        {"elf", plan.elf},
        {"plugin", ctx.plugin_path},
        {"mmap", ctx.mmap_path},
        {"mmap_size", std::to_string(ctx.mem_size)},
        {"mmap_base", ctx.mmap_base},
        {"state_in", prev_state_out},
        {"state_out", state_out},
    };
    std::vector<std::string> argv = build_argv(*tmpl, m, err);
    if (!err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + err;
      return {};
    }
    out.push_back(std::move(argv));
    prev_state_out = state_out;
  }
  err.clear();
  return out;
}

PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts) {
  PlanResult res;
  if (plan.steps.empty()) {
    res.error = "plan has no steps";
    return res;
  }

  // A private dir for the per-leg drain files each leg writes via {state_out}.
  std::error_code ec;
  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
  std::string tmpl = workdir.string();
  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
  tbuf.push_back('\0');
  const char* made = ::mkdtemp(tbuf.data());
  if (!made) {
    res.error = "failed to create plan work dir";
    return res;
  }
  const std::string wd = made;

  RuntimeCtx ctx;
  ctx.mmap_path = plan.mmap_path;  // caller-pinned; the mmap backing lands later
  ctx.mem_size = plan.mem_size;
  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps "0x0"

  std::string err;
  const std::vector<std::vector<std::string>> argvs =
      plan_argvs(plan, engines, wd, ctx, err);
  if (!err.empty()) {
    res.error = err;
  } else {
    for (size_t i = 0; i < argvs.size(); ++i) {
      const RunResult r = run_process(argvs[i], opts.timeout_ms);
      if (r.spawn_failed) {
        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
        break;
      }
      if (r.timed_out) {
        res.error = "plan step " + std::to_string(i) + ": timed out after " +
                    std::to_string(opts.timeout_ms) + " ms";
        break;
      }
      if (r.rc != opts.expect_rc) {
        res.error = "plan step " + std::to_string(i) + ": expected exit " +
                    std::to_string(opts.expect_rc) + ", got " +
                    std::to_string(r.rc);
        break;
      }
      // The per-leg mcycle/minstret readback rides in with the shared-mmap
      // backing + state-file reader (the hybrid feature); this single-phase
      // slice only proves each leg drained (exit == expect_rc).
      res.phases.push_back({});
    }
  }

  fs::remove_all(wd, ec);
  return res;
}

}  // namespace andes_sim

// Unit tests for the F6 phase-plan executor's pure core:
//   - build_argv  (driver/argv.hpp)     invoke-template placeholder fill
//   - plan_argvs  (driver/run_plan.hpp) state-file threading across steps
//
// These cover everything in run_plan EXCEPT the live spawn loop, which the
// integration acceptance (tests/andes_sim/test_andes_sim_f6.sh -> a real
// 2-step qemu+vsim run) exercises. Plain assert-and-count harness. No QEMU2 leg
// exists -- handback was removed.
#include <map>
#include <string>
#include <vector>

#include "argv.hpp"
#include "engine_descriptor.hpp"
#include "plan.hpp"
#include "run_plan.hpp"
#include "test_check.hpp"

using namespace andes_sim;
using andes_sim::test::check_eq;

namespace {

// The canonical drain templates (what builtin_qemu() and vsim --describe ship).
const std::vector<std::string> kQemuFastLeg = {
    "{bin}",
    "-object", "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
    "-machine", "andes_ae350,memory-backend=mem",
    "-cpu", "andes-ax45mpv,vlen=512",
    "-nographic",
    "-semihosting-config", "enable=on,target=native",
    "-bios", "{elf}",
    "-plugin", "{plugin},outfile={state_out}",
};

const std::vector<std::string> kVsimAccurateLeg = {
    "{bin}", "{elf}",
    "--resume-from-qemu", "{state_in}",
    "--handoff-out", "{state_out}",
    "--shared-mem-path", "{mmap}",
    "--shared-mem-size", "{mmap_size}",
    "--shared-mem-base", "{mmap_base}",
};

EngineDescriptor fake(const std::string& id, const std::string& bin,
                      const std::string& role,
                      const std::vector<std::string>& tmpl) {
  EngineDescriptor d;
  d.id = id;
  d.bin_path = bin;
  d.invoke.push_back({role, tmpl});
  return d;
}

}  // namespace

int main() {
  // --- build_argv: every placeholder filled, including substring + repeat ---
  {
    std::string err;
    std::map<std::string, std::string> ctx = {
        {"bin", "/q"},      {"elf", "/e"},     {"plugin", "/p"},
        {"mmap", "/m"},     {"mmap_size", "134217728"}, {"state_out", "/s0"},
    };
    std::vector<std::string> got = build_argv(kQemuFastLeg, ctx, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-object",
              "memory-backend-file,id=mem,share=on,mem-path=/m,size=134217728",
              "-machine", "andes_ae350,memory-backend=mem", "-cpu",
              "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
              "enable=on,target=native", "-bios", "/e", "-plugin",
              "/p,outfile=/s0"},
             "qemu");
  }
  {
    std::string err;
    std::map<std::string, std::string> ctx = {
        {"bin", "/v"},  {"elf", "/e"},  {"state_in", "/s0"},
        {"state_out", "/s1"}, {"mmap", "/m"}, {"mmap_size", "134217728"},
        {"mmap_base", "0x0"},
    };
    std::vector<std::string> got = build_argv(kVsimAccurateLeg, ctx, err);
    CHECK(err.empty());
    check_eq(got,
             {"/v", "/e", "--resume-from-qemu", "/s0", "--handoff-out", "/s1",
              "--shared-mem-path", "/m", "--shared-mem-size", "134217728",
              "--shared-mem-base", "0x0"},
             "vsim");
  }
  // a repeated placeholder expands every occurrence
  {
    std::string err;
    std::vector<std::string> got =
        build_argv({"a={x},b={y},a2={x}"}, {{"x", "1"}, {"y", "2"}}, err);
    CHECK(err.empty());
    check_eq(got, {"a=1,b=2,a2=1"}, "repeat");
  }
  // an unknown placeholder is an error, not a silent empty fill
  {
    std::string err;
    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
    CHECK(got.empty());
    CHECK(!err.empty());
  }

  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
  std::vector<EngineDescriptor> engines = {
      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
      fake("vsim:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
  };
  Plan plan;
  plan.elf = "/e";
  plan.mem_size = 134217728;
  plan.steps = {
      {"qemu", "fast-leg", {"marker", {}}},
      {"vsim:test", "accurate-leg", {"marker", {}}},
  };
  RuntimeCtx rc;
  rc.mmap_path = "/mm";
  rc.mem_size = 134217728;
  rc.mmap_base = "0x0";
  rc.plugin_path = "/pl";

  {
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rc, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      // step 0 (qemu): drains to state-0.bin; no state_in referenced
      check_eq(argvs[0],
               {"/qbin", "-object",
                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
                "enable=on,target=native", "-bios", "/e", "-plugin",
                "/pl,outfile=/wd/state-0.bin"},
               "step0");
      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
      check_eq(argvs[1],
               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
               "step1");
    }
  }
  // unknown engine id is an error
  {
    Plan bad = plan;
    bad.steps[0].engine_id = "nope";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }
  // a role the engine has no template for is an error
  {
    Plan bad = plan;
    bad.steps[1].role = "no-such-role";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }

  return andes_sim::test::report("plan");
}

// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
//
// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
// and `cycle` (a cycle-accurate engine, from reset): each resolves its engine,
// then hands off to transparent passthrough -- the ELF plus everything after
// `--` becomes the engine's own command line, run with inherited stdio, no
// timeout, and the exit code propagated, so a gdbstub / monitor / semihosting
// console all behave as if the engine were invoked directly. `hybrid` (F9)
// lands later; its dispatch arm stubs for now.
#include <cstdio>
#include <string>
#include <vector>

#include "cli.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "process.hpp"
#include "run_passthrough.hpp"

namespace andes_sim {
namespace {

// Validate the lone-ELF positional shape the standalone models require: print
// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
int check_one_elf(const Cli& cli, const char* model) {
  if (cli.positional.empty()) {
    std::fprintf(stderr,
                 "andesim run --mode %s: missing ELF (the workload to run; "
                 "e.g. a tests/fixtures/<name>.elf)\n",
                 model);
    return 2;
  }
  if (cli.positional.size() > 1) {
    std::fprintf(stderr,
                 "andesim run --mode %s: unexpected argument '%s' "
                 "(engine args go after --)\n",
                 model, cli.positional[1].c_str());
    return 2;
  }
  return 0;
}

// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
// then run the resolved engine standalone with the post-`--` args forwarded
// verbatim, inheriting stdio (an interactive gdbstub / monitor / semihosting
// console works unchanged) and propagating the exit code. The per-model engine
// + selection are resolved by the caller; `model` here only labels the
// positional diagnostics. This minimal slice does no ELF existence/arch
// validation (that lands with strict validation).
int run_standalone(const Cli& cli, const EngineDescriptor& eng,
                   const char* model) {
  if (int rc = check_one_elf(cli, model)) return rc;
  std::string err;
  const std::vector<std::string> argv = passthrough_argv(
      eng, "standalone", cli.positional[0], cli.passthrough, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
    return 2;
  }
  return exec_passthrough(argv);
}

// `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
// the built-in qemu descriptor directly (no engine discovery -- fast needs only
// qemu, and discover_engines would spawn a --describe per Verilator build).
int run_fast(const Cli& cli) {
  // fast is QEMU-only; an explicit engine must name it.
  if (!cli.engine.empty() && cli.engine != "qemu") {
    std::fprintf(stderr,
                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }
  return run_standalone(cli, builtin_qemu(), "fast");
}

// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
// no --resume-from-qemu), transparent passthrough -- cycles surface in the
// engine's own output. Unlike fast, this must discover the Verilator build(s)
// to resolve the engine (explicit --engine, else the sole one).
int run_accurate(const Cli& cli) {
  Discovery disc = discover_engines();
  std::string err;
  const EngineDescriptor* eng =
      resolve_accurate_engine(disc.engines, cli.engine, err);
  if (!eng) {
    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
    // Surface why an expected engine may be absent (failed --describe, etc.).
    for (const std::string& w : disc.warnings)
      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
    return 2;
  }
  return run_standalone(cli, *eng, "cycle");
}

}  // namespace

int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andesim run: --mode fast|cycle|hybrid is required "
                 "(pick the composition; see 'andesim run --help')\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);
  if (cli.model == "cycle") return run_accurate(cli);

  std::fprintf(stderr, "andesim run --mode %s: not yet implemented\n",
               cli.model.c_str());
  return 3;
}

}  // namespace andes_sim

